#include <stdio.h>

void echanger(int *a, int *b)
{
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int main(void)
{
    int x = 1, y = 2;
    echanger(&x, &y);
    printf("x=%d y=%d\n", x, y);   /* x=2 y=1 */
    return 0;
}

