#include <stdlib.h>

int *ajouter(int *tab, size_t *n, int valeur)
{
    int *nouveau = realloc(tab, (*n + 1) * sizeof *tab);
    if (nouveau == NULL)
        return tab;          /* l'ancien bloc reste valide */
    nouveau[*n] = valeur;
    (*n)++;
    return nouveau;
}

